24	    internal static async IAsyncEnumerable<ChatMessageContent> InvokeAsync(
25	        OpenAIResponseAgent agent,
26	        ChatHistory history,
27	        AgentThread agentThread,
28	        AgentInvokeOptions options,
29	        [EnumeratorCancellation] CancellationToken cancellationToken)
30	    {
31	        var responseAgentThread = agentThread as OpenAIResponseAgentThread;
32	
33	        var overrideHistory = history;
34	        if (!agent.StoreEnabled)
35	        {
36	            // Use the thread chat history
37	            overrideHistory = [.. GetChatHistory(agentThread)];
38	        }
39	
40	        var creationOptions = ResponseCreationOptionsFactory.CreateOptions(agent, agentThread, options);
41	
42	        var inputItems = overrideHistory.Select(c => c.ToResponseItem()).ToList();
43	        FunctionCallsProcessor functionProcessor = new();
44	        FunctionChoiceBehaviorOptions functionOptions = new() { AllowConcurrentInvocation = true, AllowParallelCalls = true, RetainArgumentTypes = true };
45	        for (int requestIndex = 0; ; requestIndex++)
46	        {
47	            // Create a response using the OpenAI Responses API
48	            creationOptions.InputItems.Clear();
49	            foreach (var item in inputItems) { creationOptions.InputItems.Add(item); }
50	            var clientResult = await agent.Client.CreateResponseAsync(creationOptions, cancellationToken).ConfigureAwait(false);
51	            var response = clientResult.Value;
52	            ThrowIfIncompleteOrFailed(agent, response);
53	
54	            // Update the response ID in the creation options
55	            if (responseAgentThread is not null)
56	            {
57	                creationOptions.PreviousResponseId = response.Id;
58	                responseAgentThread.ResponseId = response.Id;
59	            }
60	            else
61	            {
62	                var filteredItems = response.OutputItems
63	                    .Where(item => item is not ReasoningResponseItem); // Keep items that are not ReasoningResponseItem  
64	                inputItems.AddRange(filteredItems);
65	            }
66	
67	            var message = response.ToChatMessageContent();
68	            overrideHistory.Add(message);
69	            yield return message;
70	
71	            // Reached maximum auto invocations
72	            if (requestIndex == MaximumAutoInvokeAttempts)
73	            {
74	                break;
75	            }
76	
77	            // Check if there are any functions to invoke.
78	            var functionCalls = response.OutputItems
79	                .OfType<FunctionCallResponseItem>()
80	                .Select(f => f.ToFunctionCallContent())
81	                .ToList();
82	            if (functionCalls.Count == 0)
83	            {
84	                break;
85	            }
86	
87	            // Invoke functions and create function output items for results
88	            FunctionResultContent[] functionResults =
89	                await functionProcessor.InvokeFunctionCallsAsync(
90	                    message,
91	                    (_) => true,
92	                    functionOptions,
93	                    agent.GetKernel(options),
94	                    isStreaming: false,
95	                    cancellationToken).ConfigureAwait(false);
96	            var functionOutputItems = functionResults.Select(fr => ResponseItem.CreateFunctionCallOutputItem(fr.CallId, fr.Result?.ToString() ?? string.Empty)).ToList();
97	
98	            // If store is enabled we only need to send the function output items
99	            if (agent.StoreEnabled)
100	            {
101	                inputItems = [.. functionOutputItems];
102	            }
103	            else
104	            {
105	                inputItems.AddRange(functionOutputItems);
106	            }
107	
108	            // Return the function results as a message
109	            ChatMessageContentItemCollection items = [.. functionResults];
110	            ChatMessageContent functionResultMessage = new()
111	            {
112	                Role = AuthorRole.Tool,
113	                Items = items,
114	            };
115	            overrideHistory.Add(functionResultMessage);
116	            yield return functionResultMessage;
117	        }
118	    }
