2	using System.Collections.Generic;
3	using System.Linq;
4	using Microsoft.SemanticKernel.Connectors.FunctionCalling;
5	using OpenAI.Assistants;
6	
7	namespace Microsoft.SemanticKernel.Agents.OpenAI.Internal;
8	
9	/// <summary>
10	/// Factory for creating <see cref="MessageContent"/> based on <see cref="ChatMessageContent"/>.
11	/// Also able to produce <see cref="MessageCreationOptions"/>.
12	/// </summary>
13	/// <remarks>
14	/// Improves testability.
15	/// </remarks>
16	internal static class AssistantMessageFactory
17	{
18	    /// <summary>
19	    /// Produces <see cref="MessageCreationOptions"/> based on <see cref="ChatMessageContent"/>.
20	    /// </summary>
21	    /// <param name="message">The message content.</param>
22	    public static MessageCreationOptions CreateOptions(ChatMessageContent message)
23	    {
24	        MessageCreationOptions options = new();
25	
26	        if (message.Metadata != null)
27	        {
28	            foreach (var metadata in message.Metadata)
29	            {
30	                options.Metadata.Add(metadata.Key, metadata.Value?.ToString() ?? string.Empty);
31	            }
32	        }
33	
34	        return options;
35	    }
36	
37	    /// <summary>
38	    /// Translates <see cref="ChatMessageContent.Items"/> into enumeration of <see cref="MessageContent"/>.
39	    /// </summary>
40	    /// <param name="message">The message content.</param>
41	    public static IEnumerable<MessageContent> GetMessageContents(ChatMessageContent message)
42	    {
43	        bool hasTextContent = message.Items.OfType<TextContent>().Any();
44	        foreach (KernelContent content in message.Items)
45	        {
46	            if (content is TextContent textContent)
47	            {
48	                var text = content.ToString();
49	                if (string.IsNullOrWhiteSpace(text))
50	                {
51	                    // Message content must be non-empty.
52	                    continue;
53	                }
54	                yield return MessageContent.FromText(text);
55	            }
56	            else if (content is ImageContent imageContent)
57	            {
58	                if (imageContent.Uri != null)
59	                {
60	                    yield return MessageContent.FromImageUri(imageContent.Uri);
61	                }
62	                else if (!string.IsNullOrWhiteSpace(imageContent.DataUri))
63	                {
64	                    yield return MessageContent.FromImageUri(new(imageContent.DataUri!));
65	                }
66	            }
67	            else if (content is FileReferenceContent fileContent)
68	            {
69	                yield return MessageContent.FromImageFileId(fileContent.FileId);
70	            }
71	            else if (content is FunctionResultContent resultContent && resultContent.Result != null && !hasTextContent)
72	            {
73	                // Only convert a function result when text-content is not already present
74	                yield return MessageContent.FromText(FunctionCallsProcessor.ProcessFunctionResult(resultContent.Result));
75	            }
76	        }
77	    }
78	}
